using System;
using CargoWise.EntityFramework.Testing;
using CargoWise.IO;
using CargoWise.Types;
using Enterprise.ZArchitecture.Business;

namespace Enterprise.MasterFiles.Business.Testing
{
	sealed class StmTemplateDataVersionLogValueFormatterTest : TestCaseWithFactory
	{
		public void TestSerialise_Empty()
		{
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertEquals("Empty blob", string.Empty, formatter.SerialiseBinaryValueToString("SO_Template", new ZBlob()));
		}

		public void TestSerialise_NonEmpty()
		{
			var data = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			var expected = Convert.ToBase64String(Compressor.Compress(data));
			AssertEquals("Not as expected", expected, formatter.SerialiseBinaryValueToString("SO_Template", data));
		}

		public void TestSerialise_UnsupportedColumn()
		{
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertExceptionThrown(typeof(ArgumentException), "Unsupported property: dummy", () => formatter.SerialiseBinaryValueToString("dummy", new byte[] { 1, 2, 3 }));
		}

		public void TestDeserialise()
		{
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			var serialisedString = Convert.ToBase64String(Compressor.Compress(new byte[] { 32, 213, 21, 89 }));
			var expected = Compressor.Uncompress(Convert.FromBase64String(serialisedString));
			AssertEquals("Not as expected", expected, formatter.DeserialiseBinaryValueFromString("SO_Template", serialisedString));
		}

		public void TestDeserialise_UnsupportedColumn()
		{
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertExceptionThrown(typeof(ArgumentException), "Unsupported property: dummy", () => formatter.DeserialiseBinaryValueFromString("dummy", "something"));
		}

		public void TestDeserialise_Corrupted()
		{
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			var corruptedString = "y0uR31dio+1Fuc4n533M4!";
			AssertExceptionThrown(typeof(DataVersionLogValueFormatterException), "This template is corrupted and unreadable.", () => formatter.DeserialiseBinaryValueFromString("SO_Template", corruptedString));
		}

		public void TestDeserialiseBackToOriginal()
		{
			var data = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertEquals("Deserialise should be same with original", data, formatter.DeserialiseBinaryValueFromString("SO_Template", formatter.SerialiseBinaryValueToString("SO_Template", data)));
		}

		public void TestGetFileExtensionFilter()
		{
			//this is a valid excel file in string
			var excelString = @"";
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertEquals("Should be xls", "Excel files (*.XLS)|*.XLS", formatter.GetFileExtensionFilter("SO_Template", excelString));
		}

		public void TestGetFileExtensionFilter_Corrupted()
		{
			var txtString = "UFqrzC9VSCxKVUgpzc2tBAA="; // this is a valid text file but not a excel file
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertExceptionThrown(typeof(DataVersionLogValueFormatterException), "This template is not a compatible Excel file.", () => formatter.GetFileExtensionFilter("SO_Template", txtString));
		}

		public void TestGetFileExtensionFilter_UnsupportedColumn()
		{
			var formatter = new StmTemplateDataVersionLogValueFormatter();
			AssertExceptionThrown(typeof(ArgumentException), "Unsupported property: dummy", () => formatter.GetFileExtensionFilter("dummy", "something"));
		}
	}
}
